full:
TIMEOUT/ERROR: unused arguments (fun = function(sql) {
    if (!grepl("^\\s*SELECT", sql, ignore.case = TRUE)) {
        tool_log$error <<- "Only SELECT queries are allowed."
        return("Error: only SELECT queries are allowed.")
    }
    tool_log$sql <<- sql
    result <- tryCatch({
        dbGetQuery(session$gdb, sql)
    }, error = function(e) {
        tool_log$error <<- e$message
        return(NULL)
    })
    if (is.null(result)) {
        err_msg <- paste("Query error:", tool_log$error)
        tool_log$raw_result <<- err_msg
        return(err_msg)
    }
    if (nrow(result) > 200) result <- result[1:200, ]
    json_out <- toJSON(result, auto_unbox = TRUE)
    tool_log$raw_result <<- as.character(json_out)
    return(as.character(json_out))
}, name = "query_variants", description = paste0("Run a SELECT query on the varInfo_synthetic ALS variant database. ", "Returns JSON. Max 200 rows. ", "Use for any question answerable with SQL. ", "Columns: VAR_id, CHROM, POS, ID, REF, ALT, AC, AN, AF, ", "gene_name, HighImpact, ModerateImpact, Synonymous, ", "CADDphred, PolyPhen, SIFT, ", "ALS_1..ALS_5 (ALS patient genotypes 0/1/2), ", "Control_1..Control_5 (control genotypes 0/1/2). ", "Missing values for CADDphred/PolyPhen/SIFT stored as '.' not NULL."), arguments = list(sql = list(type = "string", 
    description = "A valid SQLite SELECT statement querying varInfo_synthetic.", required = TRUE)))

